import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

conv1d_source = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <vector>

// Naive forward kernel for 1D convolution (groups=1, no bias).
//   input shape:  (N, inC, inL)
//   weight shape: (outC, inC, kL)
//   output shape: (N, outC, outL)
__global__ void conv1d_forward_kernel(const float* input,
                                      const float* weight,
                                      float* output,
                                      const int N,
                                      const int inC,
                                      const int inL,
                                      const int outC,
                                      const int kL,
                                      const int stride,
                                      const int padding,
                                      const int dilation,
                                      const int outL) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    int total_threads = N * outC * outL;
    if (idx >= total_threads) {
        return;
    }

    // Decompose idx into (n, oc, oPos)
    int n   = idx / (outC * outL);
    int rem = idx % (outC * outL);
    int oc  = rem / outL;
    int oPos= rem % outL;

    float sum_val = 0.0f;
    // Compute convolution
    for (int ic = 0; ic < inC; ic++) {
        for (int k = 0; k < kL; k++) {
            int iPos = oPos * stride - padding + k * dilation;
            if (iPos >= 0 && iPos < inL) {
                // input index = n * (inC*inL) + ic*(inL) + iPos
                float val_in = input[n*inC*inL + ic*inL + iPos];
                // weight index = oc*(inC*kL) + ic*(kL) + k
                float val_wt = weight[oc*inC*kL + ic*kL + k];
                sum_val += val_in * val_wt;
            }
        }
    }

    // Store result
    // output index = n*(outC*outL) + oc*outL + oPos
    output[n*outC*outL + oc*outL + oPos] = sum_val;
}

torch::Tensor conv1d_cuda_forward(torch::Tensor input,
                                  torch::Tensor weight,
                                  int stride,
                                  int padding,
                                  int dilation) {
    // Expect input to be 3D: (N, inC, inL)
    // Expect weight to be 3D: (outC, inC, kernel_size)
    TORCH_CHECK(input.dim() == 3, "Input must be a 3D tensor");
    TORCH_CHECK(weight.dim() == 3, "Weight must be a 3D tensor");

    const int N   = input.size(0);
    const int inC = input.size(1);
    const int inL = input.size(2);

    const int outC = weight.size(0);
    TORCH_CHECK(weight.size(1) == inC, "Weight in_channels must match input in_channels");
    const int kL = weight.size(2);

    // Compute output length
    int outL = (inL + 2*padding - dilation*(kL - 1) - 1) / stride + 1;
    TORCH_CHECK(outL > 0, "Output length must be positive. Check your stride/padding/dilation/kernel_size.");

    auto options = input.options();
    auto output = torch::empty({N, outC, outL}, options);

    // Flatten the tensors for simple indexing on device
    auto input_contig  = input.contiguous();
    auto weight_contig = weight.contiguous();
    auto output_contig = output.contiguous();

    const float* input_ptr  = input_contig.data_ptr<float>();
    const float* weight_ptr = weight_contig.data_ptr<float>();
    float* output_ptr       = output_contig.data_ptr<float>();

    // Launch kernel
    int total_threads = N * outC * outL;
    int block_size = 256;
    int grid_size = (total_threads + block_size - 1) / block_size;

    conv1d_forward_kernel<<<grid_size, block_size>>>(
        input_ptr,
        weight_ptr,
        output_ptr,
        N,
        inC,
        inL,
        outC,
        kL,
        stride,
        padding,
        dilation,
        outL
    );

    return output;
}
"""

conv1d_cpp_source = r"""
torch::Tensor conv1d_cuda_forward(torch::Tensor input,
                                  torch::Tensor weight,
                                  int stride,
                                  int padding,
                                  int dilation);
"""

conv1d = load_inline(
    name="conv1d_extension",
    cpp_sources=conv1d_cpp_source,
    cuda_sources=conv1d_source,
    functions=["conv1d_cuda_forward"],
    verbose=False,
)


class ModelNew(nn.Module):
    """
    Custom 1D convolution using a naive CUDA kernel.
    Currently supports groups=1 and bias=False only.
    """
    def __init__(
        self,
        in_channels: int,
        out_channels: int,
        kernel_size: int,
        stride: int = 1,
        padding: int = 0,
        dilation: int = 1,
        groups: int = 1,
        bias: bool = False
    ):
        super(ModelNew, self).__init__()
        if groups != 1:
            raise NotImplementedError("groups != 1 not supported in this custom kernel.")
        if bias:
            raise NotImplementedError("bias=True not supported in this custom kernel.")

        self.in_channels = in_channels
        self.out_channels = out_channels
        self.kernel_size = kernel_size
        self.stride = stride
        self.padding = padding
        self.dilation = dilation

        # Register weight as a trainable parameter (no bias).
        # Shape: (out_channels, in_channels, kernel_size)
        self.weight = nn.Parameter(
            torch.randn(out_channels, in_channels, kernel_size)
        )

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        """
        Perform custom 1D convolution on input x using a naive CUDA kernel.
        Args:
            x (torch.Tensor): shape (N, inC, inL)
        Returns:
            torch.Tensor: shape (N, outC, outL)
        """
        return conv1d.conv1d_cuda_forward(
            x, self.weight, self.stride, self.padding, self.dilation
        )
